// ---------------------------------------------------------------------------
// BFX_ASSETS — AI-generated art (Higgsfield / GPT Image 2.5, Sept 2026), inlined
// as WebP data URLs so the game stays one self-contained file.
//   skies[i]      2048x878 panoramic backdrop for circuit i (0..5), horizon at the
//                 vertical centre. Meant to be wrapped on a cylinder/dome around the track.
//   keyArt.title  1920x1080 hero image for the title screen (left third is calm → title goes there)
//   keyArt.finish 1600x900 alternate hero (results / grand prix screens)
//   portraits[i]  512x512 transparent-background bust of driver i (Blu..Pixel)
//   load(url) -> Promise<HTMLImageElement>  (cached)
// ---------------------------------------------------------------------------
var BFX_ASSETS = (function () {
  const A = {"skies": ["data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,"], "keyArt": {"title": "data:image/webp;base64,", "finish": "data:image/webp;base64,"}, "portraits": ["data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,"]};
  const cache = new Map();
  A.load = function (url) {
    if (cache.has(url)) return cache.get(url);
    const p = new Promise((res, rej) => { const im = new Image(); im.onload = () => res(im); im.onerror = rej; im.src = url; });
    cache.set(url, p); return p;
  };
  A.names = ["Blu","Nova","Knox","Frost","Blaze","Glitch","Onyx","Pixel"];
  A.circuits = ["Chicago Afterglow","Xfinity Megastore","Lakefront Rush","Frostbyte Summit","Signal Canyon","Gigabit Galaxy"];
  if (typeof window !== "undefined") window.__BFX_ASSETS = A;
  return A;
})();
